  'ad_cop_47_0': const AbuDhabiHseTopicContent(
    overview: 'CoP 47.0 — Machine Guarding. Gold Standard Abu Dhabi HSE content covering machine safeguarding, hazardous moving parts, inspection and field controls.',
    deepStudy: const <String>[
      'Understand the purpose of machine guarding: prevent access to dangerous moving parts, nip points, rotating components, cutting zones and stored-energy hazards.',
      'Apply the hierarchy of controls by eliminating exposure where possible and using fixed or interlocked guarding before relying on administrative controls or PPE.',
      'Assess machinery during normal operation, cleaning, adjustment, fault finding, maintenance, jam clearing and isolation—not only during production.',
      'Ensure guards are suitable, securely fixed, difficult to defeat, compatible with the machine function and accessible for inspection and maintenance.',
      'Integrate machine safeguarding with isolation/LOTO, competent maintenance, manufacturer instructions and emergency-stop arrangements.',
    ],
    microDetails: const <String>[
      'Check for exposed gears, belts, chains, shafts, blades, rollers, augers, presses, shears and other dangerous moving parts.',
      'Verify fixed guards are present, secure and not bypassed; inspect interlocks and protective devices where fitted.',
      'Keep operators clear of reach-through and reach-around access to danger zones.',
      'Never remove a guard for convenience; require isolation before guard removal for maintenance or adjustment.',
      'Control access to machinery during commissioning, testing and troubleshooting.',
    ],
    fieldPractical: const <String>[
      'Conduct a pre-use safeguarding inspection and compare guards with the approved equipment arrangement.',
      'Observe an operator cycle to identify unsafe access, defeated interlocks or workarounds.',
      'Confirm isolation points are identified and workers understand the machine-specific isolation procedure.',
      'Stop work when a critical guard or protective device is missing, damaged or defeated.',
      'Record defects and ensure corrective actions are closed before return to service.',
    ],
    inspectionChecklist: const <String>[
      'Guarding covers all identified danger zones',
      'Guards securely attached and not easily defeated',
      'Interlocks/safety devices functional where provided',
      'Emergency-stop devices accessible and tested as required',
      'Isolation points identified and accessible',
      'Inspection and corrective-action status current',
    ],
    emergencyResponse: const <String>[
      'Isolate the machine before rescue or intervention where safe to do so.',
      'Prevent restart and control stored energy.',
      'Provide first aid/emergency response for entanglement, crushing or amputation events.',
      'Preserve the scene and report the incident through the site process.',
    ],
    records: const <String>[
      'Risk assessment and machine-specific safe operating procedure',
      'Manufacturer manual and guarding/safeguarding information',
      'Inspection and maintenance records',
      'LOTO/isolation records where applicable',
      'Training/competency and incident/corrective-action records',
    ],
    interviewQuestions: const <String>[
      'How do you identify dangerous machine access points?',
      'What makes a machine guard effective and reliable?',
      'When must machine guarding be combined with isolation/LOTO?',
      'What would make you stop a machine immediately during an inspection?',
