    deepStudy: const <String>[
      'Assess spray-finishing hazards from paints, solvents, thinners, aerosols, vapours, overspray, compressed air and ignition sources.',
      'Use suitable spray areas, booths or controlled locations with effective ventilation and capture of contaminants.',
      'Control ignition sources and static electricity where flammable or combustible materials can create a fire or explosion atmosphere.',
