    deepStudy: const <String>[
      'Understand hazards from stored pressure, cylinder rupture, hose failure, uncontrolled release, oxygen enrichment, flammable/toxic gases and incorrect connections.',
      'Use cylinders and compressed-air equipment that are suitable, identifiable, inspected and maintained for the service and pressure involved.',
      'Control storage, segregation, securing, transport, connection and use of cylinders to prevent falling, damage, leakage and incompatible combinations.',
      'Prevent misuse of compressed air for cleaning people or unsafe blow-off activities and control line-of-fire exposure.',
      'Integrate pressure-relief, isolation, ventilation, leak detection and emergency arrangements into the safe system of work.',
    ],
    microDetails: const <String>[
      'Secure cylinders upright where required and protect valves during transport.',
      'Check labels, condition, hoses, regulators, connections and fittings before use.',
      'Keep incompatible gases appropriately segregated and protect cylinders from heat and impact.',
      'Use the correct regulator and fittings for the gas/service.',
      'Control compressed-air pressure and never direct compressed air toward a person.',
    ],
