      'Use suitable blast equipment, hoses, couplings, dead-man controls, blast nozzles and containment systems that are maintained and inspected.',
      'Control exposure through enclosure/containment, local exhaust or suitable ventilation, wet methods where appropriate, housekeeping and correctly selected respiratory protection.',
