      'Ensure trucks are suitable for the load, environment, terrain and task and are maintained in safe operating condition.',
      'Control operator authorization, competency, pre-use checks, seat-belt use where fitted, speed, visibility and safe travel routes.',
      'Plan load handling around rated capacity, load centre, stability, stacking, ramps, edges and overhead hazards.',
      'Separate pedestrians and vehicles wherever reasonably practicable and control reversing, parking, charging/refuelling and attachments.',
