        example: 'An entry identifies an asbestos cement panel, its exact room/roof location, survey reference, condition and accessibility.',
        hazards: 'Incomplete information can lead to wrong work methods.',
        controls: 'Use a standard register format and mandatory fields.',
        fieldCheck: 'Sample several entries against the CoP minimum information.',
        commonMistake: 'Recording only \'asbestos present\' without location or material type.',
        action: 'Update incomplete entries before relying on them for work planning.',
        records: 'Register; drawings; sample results; condition records.',
