        title: 'Condition and control information',
        meaning: 'The register should support risk assessment by recording condition, accessibility, surrounding environment and appropriate control measures.',
        explanation: 'The same material can present different management needs depending on damage, accessibility and planned activities nearby.',
        example: 'An intact ceiling board is controlled differently from a damaged board in a frequently accessed service corridor.',
        hazards: 'Condition deterioration and repeated disturbance can increase exposure risk.',
        controls: 'Assign control measures and review when conditions change.',
        fieldCheck: 'Walk down high-risk register entries and compare actual conditions.',
        commonMistake: 'Failing to update the register after damage or maintenance.',
        action: 'Update the register and risk assessment after significant change.',
        records: 'Inspection records; updated register; risk assessment.',
