        title: 'Assess each ACM',
        meaning: 'Materials with identified or presumed asbestos fibres must be risk assessed so appropriate control measures can be assigned.',
        explanation: 'The assessment should consider condition, accessibility, material type, disturbance potential and surrounding work.',
        example: 'A risk assessment identifies a damaged pipe lagging area near a maintenance route as requiring immediate control.',
        hazards: 'Exposure can occur from direct disturbance or secondary contamination.',
        controls: 'Use competent assessment, prioritisation and documented control measures.',
        fieldCheck: 'Check that every significant register entry has a management decision.',
        commonMistake: 'Using one generic risk rating for every ACM.',
        action: 'Apply material- and task-specific controls.',
        records: 'Risk assessments; register control fields; action plans.',
      ),
      CopGoldPoint(
        clause: '3.11(b)',
        title: 'Hierarchy and exposure prevention',
        meaning: 'Controls should reduce the likelihood of fibre release and worker exposure rather than relying only on PPE.',
        explanation: 'The most effective approach is to avoid disturbance, isolate the material and use controlled removal when required.',
        example: 'A project redesigns a cable route to avoid drilling into an ACM wall rather than removing the ACM unnecessarily.',
        hazards: 'Engineering or work-practice failure can create airborne fibres.',
        controls: 'Prefer avoidance, isolation and controlled methods; supplement with PPE and monitoring.',
