        explanation: 'Asbestos risk is dynamic during demolition and maintenance.',
        example: 'A change from manual stripping to mechanical cutting triggers a revised risk assessment and removal method.',
        hazards: 'Changed methods can generate much higher fibre release.',
        controls: 'Use formal management of change and stop-work triggers.',
        fieldCheck: 'Ask whether the current method matches the approved risk assessment.',
        commonMistake: 'Continuing under an old RAMS after the task changes.',
        action: 'Stop, reassess and obtain approval before changing the method.',
        records: 'MOC; revised risk assessment; revised plan of work.',
      ),
