        clause: '3.12(a)',
        title: 'Management plan requirement',
        meaning: 'Premises containing or presumed to contain asbestos must have an asbestos management plan.',
        explanation: 'The plan is the building-level system that explains how asbestos is identified, recorded, communicated, maintained and managed.',
        example: 'A facilities department keeps the plan with the current register, responsibilities, review arrangements and contractor controls.',
        hazards: 'Without a plan, individual maintenance teams may make inconsistent decisions.',
        controls: 'Maintain one controlled plan with revision history and clear responsibilities.',
        fieldCheck: 'Check the plan revision and compare it with the current register.',
        commonMistake: 'Treating the survey report as the entire management plan.',
        action: 'Develop and maintain the full management plan.',
        records: 'Management plan; revision history; register.',
      ),
      CopGoldPoint(
