        meaning: 'The management plan is developed by a competent ASC meeting the applicable registration requirements.',
        explanation: 'Specialist input ensures that the plan reflects asbestos risk and the building\'s work patterns.',
        example: 'The ASC develops the plan after reviewing the survey, register, maintenance activities and stakeholder needs.',
        hazards: 'A weak plan may omit high-risk areas or contractor interfaces.',
        controls: 'Use competent specialist development and duty-holder approval.',
        fieldCheck: 'Verify the plan\'s author and approval.',
