        explanation: 'The plan should tell a worker or contractor how asbestos is managed at that building.',
        example: 'The plan describes who to contact, how work is approved, where the register is kept, how changes are reviewed and how emergencies are handled.',
        hazards: 'Missing communication and review controls can undermine the register.',
        controls: 'Use a controlled index and periodic review.',
        fieldCheck: 'Check that the plan covers responsibilities, register, review triggers and work controls.',
        commonMistake: 'Leaving the plan incomplete after the initial survey.',
        action: 'Complete and approve the plan before relying on it.',
        records: 'Plan sections; review log; communication records.',
      ),
    ],
