        title: 'Contractor selection awareness',
        meaning: 'People involved in contractor selection must understand the asbestos management plan and how its requirements will be implemented.',
        explanation: 'Asbestos controls must be embedded before a contractor is selected, not added after mobilisation.',
        example: 'The procurement team includes asbestos competency and plan compliance requirements in the tender.',
        hazards: 'Unqualified contractors may price or plan work using unsafe assumptions.',
        controls: 'Include asbestos requirements in prequalification, tender, RAMS and contract documents.',
        fieldCheck: 'Review one contractor package for asbestos requirements.',
        commonMistake: 'Selecting a contractor on cost without checking asbestos competence.',
        action: 'Reassess the contractor before award or mobilisation.',
