      ),
      CopGoldPoint(
        clause: '3.13(b)',
        title: 'Contractor management procedure',
        meaning: 'A contractor management procedure should incorporate ADOSH-SF contractor-management requirements and the asbestos controls in the CoP.',
        explanation: 'The building owner must control interfaces between the contractor and building occupants.',
        example: 'A facilities contractor receives asbestos induction, register access, permit requirements and emergency contacts.',
        hazards: 'Poor contractor control can expose workers and building occupants.',
        controls: 'Use induction, permit, supervision, monitoring and close-out controls.',
