        title: 'Risk assessment before work',
        meaning: 'No asbestos work should proceed until the exposure risk to employees and affected persons has been assessed.',
        explanation: 'The plan of work must be built on the actual risk assessment, not a generic method.',
        example: 'Before removing ceiling panels, the contractor assesses fibre release, occupants, containment, access, decontamination and waste.',
        hazards: 'Unassessed exposure can affect workers and adjacent occupants.',
