        title: 'Refurbishment or demolition survey',
        meaning: 'Major refurbishment or demolition requires the survey scope appropriate to the intrusive work so the amount and type of asbestos likely to be disturbed are known.',
        explanation: 'The survey must be aligned with the planned extent of demolition/refurbishment.',
        example: 'A demolition project verifies concealed floor, wall, ceiling and service materials before strip-out.',
        hazards: 'Hidden ACM may be disturbed by demolition equipment.',
        controls: 'Complete the appropriate survey before intrusive demolition/refurbishment.',
