        explanation: 'Boundary decisions should consider ACM condition, work method, access, ventilation and possible contamination paths.',
        example: 'The ASC and contractor sign off the enclosure and controlled access boundary before mobilisation.',
        hazards: 'Disagreement or late changes can cause unplanned exposure.',
