        title: 'Restrict access',
        meaning: 'The asbestos work area and removal site must be secured so unauthorised people cannot enter.',
        explanation: 'Access control protects workers, visitors and building occupants from accidental exposure.',
        example: 'A locked access point and controlled entry log are used for an enclosed removal area.',
