        explanation: 'A physical barrier is part of the exposure-control system, not only a visual warning.',
        example: 'The perimeter is inspected at shift start, during work and after incidents or weather events.',
        hazards: 'Broken barriers can allow people into contaminated areas.',
        controls: 'Include barrier inspection in daily supervision and emergency response.',
        fieldCheck: 'Look for gaps, damaged tape, open doors and uncontrolled routes.',
