        title: 'Minimise people and prepare resources',
        meaning: 'Preparation includes reducing the number of people present and bringing correct tools, PPE, decontamination materials, barricades and warning signs before work begins.',
        explanation: 'Good preparation prevents workers from improvising during asbestos removal.',
        example: 'The supervisor confirms tools, PPE, wetting equipment, waste bags and decontamination supplies before opening the work area.',
        hazards: 'Missing equipment can lead to uncontrolled removal or unnecessary movement through the area.',
        controls: 'Use a pre-start checklist and material/equipment staging area.',
