        title: 'Protect surfaces from contamination',
        meaning: 'Plastic sheeting or equivalent containment may be needed on surfaces likely to become contaminated; existing surfaces should be cleaned appropriately before work.',
        explanation: 'Preparation reduces the amount of residual contamination that later has to be cleaned.',
        example: 'A work area floor is protected with heavy-duty sheeting before removal of damaged ACM.',
        hazards: 'Dust and debris can settle on rough or porous surfaces and be difficult to remove.',
        controls: 'Select suitable containment and cleaning methods based on the task.',
