  CopGoldSection(
    title: '3.19. Wet and Dry Methods for Removing ACM',
    introduction: 'Sets the preferred approach to minimise airborne fibre generation during removal.',
    points: <CopGoldPoint>[
      CopGoldPoint(
        clause: '3.19(a)',
        title: 'Avoid dry working where reasonably practicable',
        meaning: 'Dry ACM should not normally be worked on where a technique can prevent or reduce airborne fibre generation.',
        explanation: 'The removal method should be selected for fibre control, not convenience.',
        example: 'A controlled wet method is selected for suitable asbestos cement rather than dry cutting.',
        hazards: 'Dry disturbance can generate substantially more airborne fibres.',
        controls: 'Use wet methods where reasonably practicable and document why another method is necessary.',
        fieldCheck: 'Check the removal method against the risk assessment.',
        commonMistake: 'Choosing dry removal because it is faster.',
        action: 'Stop and use a lower-emission method where feasible.',
        records: 'Risk assessment; method statement; method selection record.',
      ),
      CopGoldPoint(
        clause: '3.19(b)',
        title: 'Control fibre generation',
        meaning: 'Removal techniques must prevent or minimise airborne fibre generation as far as reasonably practicable.',
        explanation: 'Controls include wetting, containment, low-disturbance tools, extraction and controlled handling.',
        example: 'Workers wet the ACM, use hand tools and place removed pieces directly into labelled waste containers.',
        hazards: 'Fibre release can contaminate the work area and adjacent spaces.',
        controls: 'Combine method controls rather than relying on a single measure.',
        fieldCheck: 'Observe actual work practices, not only paperwork.',
        commonMistake: 'Using the right method on paper but working dry in practice.',
        action: 'Stop unsafe work and re-brief the crew.',
        records: 'Site inspection; toolbox talk; monitoring results.',
