        title: 'Preferred wet method',
        meaning: 'Wet spray is preferred where suitable because wetting suppresses fibre release during removal.',
        explanation: 'The material should be adequately wetted before and during disturbance without creating secondary hazards.',
        example: 'A low-pressure wetting system keeps the ACM saturated while workers remove it in controlled sections.',
