        controls: 'Use low-pressure wetting, verify saturation and control water-related hazards.',
        fieldCheck: 'Check that the wetting system is functioning and material remains adequately wetted.',
        commonMistake: 'Using high-pressure spray that damages the ACM or spreads contamination.',
        action: 'Stop, correct the wetting method and reassess electrical/slip hazards.',
        records: 'Method statement; equipment inspection; site checklist.',
      ),
      CopGoldPoint(
        clause: '3.20(b)',
        title: 'Remove wetted ACM in controlled sections',
        meaning: 'Wetted ACM should be removed in manageable sections and placed immediately into correctly labelled, sealed asbestos-waste containers.',
        explanation: 'The aim is to minimise dropping, breaking and secondary contamination.',
        example: 'Small wetted pieces are handed directly into a labelled waste bag without being thrown or dragged.',
        hazards: 'Broken dry pieces can release fibres and contaminate surfaces.',
