        explanation: 'Method selection must consider the full risk picture, not asbestos alone.',
        example: 'An electrical area is assessed and the team determines that water would create a serious electrical hazard; a controlled alternative is approved.',
        hazards: 'Water can create shock, equipment damage or slip hazards.',
        controls: 'Document the reason for selecting another method and add equivalent fibre controls.',
        fieldCheck: 'Check the method justification and controls.',
        commonMistake: 'Switching to dry removal without a revised risk assessment.',
        action: 'Obtain competent approval before using the alternative method.',
        records: 'Risk assessment; method justification; approval.',
      ),
    ],
