        title: 'Use only when wet method is unsuitable',
        meaning: 'Dry removal is the least preferred method and should be used only where the wet method is not appropriate.',
        explanation: 'Examples include live electrical conductors or major electrical equipment that could be damaged or made dangerous by water.',
        example: 'A controlled dry method is selected only after the project documents the electrical constraint and approves stronger containment and respiratory controls.',
