        clause: '3.22.1',
        title: 'Tool selection',
        meaning: 'Tools should be selected to minimise airborne fibre generation; manual tools are generally preferred.',
        explanation: 'High-speed abrasive power tools can generate and disperse asbestos fibres and should not be used for asbestos removal.',
        example: 'Workers use hand tools and, where necessary, controlled low-speed battery tools with dust controls.',
