        controls: 'Avoid high-speed abrasive tools; use low-disturbance methods and suitable extraction/wetting.',
        fieldCheck: 'Inspect tools at the start of the task.',
        commonMistake: 'Using an angle grinder or high-speed drill because it is faster.',
        action: 'Stop work and replace the tool/method.',
        records: 'Tool register; inspection checklist; RAMS.',
      ),
      CopGoldPoint(
        clause: '3.22.2',
        title: 'Spray equipment',
        meaning: 'Wet removal requires a suitable low-pressure water supply; high-pressure spray equipment must not be used.',
        explanation: 'The purpose is controlled wetting rather than blasting or dispersing contaminated material.',
        example: 'A low-pressure sprayer provides a controlled wetting pattern at the removal point.',
        hazards: 'High-pressure water can damage ACM and spread contamination.',
        controls: 'Use low-pressure equipment and inspect hoses, nozzles and connections.',
        fieldCheck: 'Observe the spray pressure and application.',
        commonMistake: 'Using a pressure washer for asbestos removal.',
        action: 'Stop immediately and replace the equipment.',
        records: 'Equipment inspection; method statement.',
      ),
      CopGoldPoint(
        clause: '3.22.3',
        title: 'Asbestos vacuum cleaners',
        meaning: 'Asbestos vacuum cleaners must meet the specified hazardous-dust/HEPA performance requirements; domestic vacuum cleaners are unsuitable.',
        explanation: 'Specialist vacuums are used for controlled collection of small dust/debris and must not be used as a substitute for safe removal technique.',
        example: 'A specialist asbestos vacuum is inspected before use and its hose/attachments are stored in a labelled impervious bag.',
        hazards: 'A domestic vacuum can redistribute fibres and become contaminated.',
        controls: 'Use compliant asbestos vacuums, controlled maintenance and suitable filters.',
        fieldCheck: 'Check the vacuum label, condition, filter status and maintenance record.',
        commonMistake: 'Using a household HEPA vacuum.',
        action: 'Remove unsuitable equipment from site and provide compliant equipment.',
        records: 'Vacuum register; maintenance record; filter record.',
      ),
      CopGoldPoint(
        clause: '3.22.4',
        title: 'Equipment inspection frequency',
        meaning: 'Equipment must be inspected before removal work, after repairs and at least every seven days when continuously used.',
        explanation: 'Inspection records demonstrate that equipment remains fit for asbestos work.',
        example: 'The supervisor checks the vacuum, pressure equipment and other removal equipment before each job and records the scheduled inspection.',
        hazards: 'Equipment failure can compromise containment or cleaning.',
        controls: 'Use a controlled inspection register and repair/withdraw defective equipment.',
        fieldCheck: 'Check inspection dates and repair status.',
        commonMistake: 'Continuing with equipment past inspection or after an unresolved defect.',
        action: 'Remove from service until repaired and inspected.',
        records: 'Equipment register; inspection records; repair records.',
      ),
    ],
  ),
  CopGoldSection(
    title: '3.23. Personal Protective Equipment (PPE)',
    introduction: 'Defines respiratory protection, protective clothing, gloves and footwear requirements for asbestos removal.',
    points: <CopGoldPoint>[
      CopGoldPoint(
        clause: '3.23.1(a-g)',
        title: 'Respiratory protective equipment',
        meaning: 'All persons engaged in asbestos removal must use RPE appropriate to the task and applicable PPE requirements; respirators require individual issue, maintenance and correct fit.',
        explanation: 'Respiratory protection is a critical secondary control and must be selected by a competent person based on the task and expected exposure.',
        example: 'A removal team is issued suitable respirators, trained in use and fit-tested where a facial seal is required.',
        hazards: 'Poor fit, damaged equipment, facial hair or incorrect use can undermine respiratory protection.',
        controls: 'Use task-appropriate RPE, fit testing where required, cleaning, maintenance and records.',
        fieldCheck: 'Check each worker\'s RPE, fit-test status and maintenance condition.',
        commonMistake: 'Giving workers a mask without checking fit or training.',
        action: 'Stop the task until suitable RPE and fit controls are in place.',
        records: 'RPE issue; fit-test; training; maintenance records.',
      ),
      CopGoldPoint(
        clause: '3.23.1(h-m)',
        title: 'Supplied-air and special RPE arrangements',
        meaning: 'Where negative-pressure RPE is medically unsuitable, appropriate positive-pressure/continuous-flow arrangements may be required; supplied-air systems need suitable backup and air-quality controls.',
        explanation: 'RPE selection must account for the person, task and enclosure conditions.',
        example: 'A worker who cannot safely use negative-pressure RPE is assessed medically and provided an appropriate alternative where reasonably practicable.',
        hazards: 'RPE failure or poor compressor air can expose workers.',
        controls: 'Maintain compressors, backup filters, air intake quality and hose/manifold arrangements.',
        fieldCheck: 'Inspect the RPE system and compressor before entry.',
        commonMistake: 'Using a supplied-air system without checking its air source or backup.',
        action: 'Stop entry and correct the RPE system.',
        records: 'Medical/fitness assessment; RPE inspection; compressor checks.',
      ),
      CopGoldPoint(
        clause: '3.23.2',
        title: 'Protective clothing and footwear',
        meaning: 'Protective clothing must be suitable for fibre control and worn in the asbestos work area until the required clearance stage; disposable coveralls are preferred and are not reused.',
        explanation: 'Clothing should minimise fibre retention and allow controlled decontamination.',
        example: 'Workers wear suitable disposable coveralls without external features that make decontamination difficult.',
        hazards: 'Contaminated clothing can carry fibres outside the work area.',
        controls: 'Use suitable coveralls, gloves and footwear; control removal and disposal.',
        fieldCheck: 'Check coverall condition and disposal arrangements.',
        commonMistake: 'Taking contaminated coveralls home or reusing disposable coveralls.',
        action: 'Stop the practice and treat contaminated clothing as asbestos waste as required.',
        records: 'PPE issue records; disposal records; decontamination checklist.',
      ),
    ],
  ),
  CopGoldSection(
    title: '3.24. Air Monitoring',
    introduction: 'Requires monitoring during removal to demonstrate that fibre controls are effective and to support clearance decisions.',
    points: <CopGoldPoint>[
      CopGoldPoint(
        clause: '3.24(a-d)',
        title: 'Monitoring programme',
        meaning: 'Air monitoring is required during ACM removal; a competent person independent of the removal activity determines the sampling locations, rate and frequency based on the work.',
        explanation: 'Monitoring should consider the ACM type, location, enclosure, building occupancy and potential exposure pathways.',
        example: 'The monitoring plan includes the work area, adjacent occupied areas and other locations where exposure could occur.',
        hazards: 'Poorly designed sampling can miss a release.',
        controls: 'Use a written monitoring programme and competent sampling design.',
        fieldCheck: 'Check the monitoring plan before work starts.',
        commonMistake: 'Using a fixed sampling routine regardless of the job.',
        action: 'Revise the monitoring plan when conditions or work methods change.',
        records: 'Air-monitoring programme; sampling plan; results.',
      ),
      CopGoldPoint(
        clause: '3.24(e-g)',
        title: 'Monitoring before removal starts',
        meaning: 'Written monitoring programmes are required for specified friable ACM removals, and removal work must not begin until monitoring has commenced.',
        explanation: 'The first measurement establishes a baseline and confirms the monitoring system is operational.',
        example: 'Background monitoring is completed before removal begins inside an enclosure.',
        hazards: 'Starting without monitoring can make it harder to detect an early control failure.',
        controls: 'Set up and verify monitoring before authorising removal.',
        fieldCheck: 'Check sampler placement and start time against the work permit.',
        commonMistake: 'Starting removal while the monitor is still being prepared.',
        action: 'Delay the start until monitoring is active.',
        records: 'Pre-start monitoring result; permit; sampler log.',
      ),
      CopGoldPoint(
        clause: '3.24(h-j)',
        title: 'Sampler locations and enclosure monitoring',
        meaning: 'Sampling locations must avoid poor air mixing or fast air movement; enclosure work requires monitoring at defined stages and relevant decontamination/adjacent locations.',
        explanation: 'Monitoring should represent the areas where people could actually be exposed.',
        example: 'Sampling is placed appropriately inside the work area and at relevant boundaries rather than directly in an air-conditioning jet.',
        hazards: 'Poor placement can produce misleading results.',
        controls: 'Follow the competent monitoring plan and record exact sampling locations.',
        fieldCheck: 'Physically inspect sampler positions.',
        commonMistake: 'Moving samplers to convenient but unrepresentative locations.',
        action: 'Correct the position and document the change.',
        records: 'Sampling map; field sheet; photographs.',
      ),
      CopGoldPoint(
        clause: '3.24(k)',
        title: 'Communicate monitoring results',
        meaning: 'Air-monitoring results must be provided to relevant parties as soon as reasonably practicable.',
        explanation: 'Results support decisions about continuing work, reviewing controls and clearance.',
        example: 'A significant result is immediately communicated to the ASC, contractor and duty holder.',
        hazards: 'Delayed information can allow unsafe work to continue.',
        controls: 'Define result-reporting routes and escalation thresholds.',
        fieldCheck: 'Check the time between sampling, result and action.',
        commonMistake: 'Keeping results only in the laboratory file.',
        action: 'Communicate and escalate results promptly.',
        records: 'Monitoring reports; email/notification record; action log.',
      ),
    ],
  ),
  CopGoldSection(
    title: '3.24.1. Control Levels for Monitored Airborne Asbestos Fibers',
    introduction: 'Defines the action levels used to judge control effectiveness during monitoring.',
    points: <CopGoldPoint>[
      CopGoldPoint(
        clause: '3.24.1(a)',
        title: 'Control levels are action triggers',
        meaning: 'Control levels indicate when existing controls need review or other action; they are occupational-hygiene best-practice controls rather than health-based standards.',
        explanation: 'The values are used to trigger management action, not to declare a fibre concentration \'safe\'.',
        example: 'A result reaches a review level and the team stops to investigate why the control performance changed.',
        hazards: 'Failure to act on elevated results can allow continued exposure.',
        controls: 'Use the specified action levels as part of the monitoring response plan.',
        fieldCheck: 'Check that each result has a documented decision.',
        commonMistake: 'Treating the action level as a permission to continue without review.',
        action: 'Review controls and escalate according to the specified level.',
        records: 'Monitoring results; action records; revised controls.',
      ),
      CopGoldPoint(
        clause: '3.24.1(b)',
        title: 'Below 0.01 fibres/mL',
        meaning: 'The CoP table indicates that below 0.01 fibres/mL the existing control measures can continue, subject to the overall work controls.',
        explanation: 'The result should still be interpreted by the competent person in the context of the task and monitoring programme.',
        example: 'A result below 0.01 fibres/mL is recorded and the team continues the approved controls.',
        hazards: 'A single result does not remove the need for ongoing control.',
        controls: 'Continue the approved method and monitoring programme.',
        fieldCheck: 'Check that work controls remain unchanged.',
        commonMistake: 'Assuming one low result means monitoring can stop.',
        action: 'Continue monitoring as required by the programme.',
        records: 'Monitoring report; daily log.',
      ),
      CopGoldPoint(
        clause: '3.24.1(c)',
        title: 'At or above 0.01 and 0.02 fibres/mL',
        meaning: 'The table requires review at or above 0.01 fibres/mL and stopping removal work to find the cause at or above 0.02 fibres/mL.',
        explanation: 'These thresholds create progressively stronger action requirements.',
        example: 'A result of 0.015 fibres/mL triggers control review; a result of 0.021 fibres/mL triggers stopping removal and investigating the cause.',
        hazards: 'Continuing despite the stop threshold can increase exposure and contamination.',
        controls: 'Use a written escalation procedure and empower supervisors to stop work.',
        fieldCheck: 'Verify the result is linked to a documented action.',
        commonMistake: 'Arguing about the result instead of implementing the required response.',
        action: 'Review/stop as applicable, identify the cause, correct controls and obtain competent clearance to restart.',
        records: 'Monitoring result; investigation; corrective action; restart approval.',
      ),
    ],
  ),
  CopGoldSection(
    title: '3.25. Decontamination',
    introduction: 'Controls decontamination of the work area, equipment, tools, personnel and potentially contaminated surfaces.',
    points: <CopGoldPoint>[
