        title: 'Decontamination strategy',
        meaning: 'The required decontamination method depends on asbestos type, work method and site conditions and must cover the work area, tools and equipment.',
        explanation: 'Decontamination should prevent asbestos from leaving the controlled area.',
        example: 'A wet-wipe and specialist-vacuum procedure is used for suitable surfaces and tools after removal.',
        hazards: 'Residual dust can contaminate workers and adjacent areas.',
        controls: 'Plan wet/dry decontamination, use suitable materials and prevent cross-contamination.',
