        example: 'Hand tools are cleaned under controlled conditions or sealed and dedicated to asbestos work.',
        hazards: 'Contaminated equipment can transfer fibres to vehicles or other sites.',
        controls: 'Use dedicated equipment or controlled decontamination and sealed storage.',
