        explanation: 'Personal decontamination is a key barrier against take-home or secondary exposure.',
        example: 'Workers follow the controlled sequence for cleaning coveralls, footwear and RPE before leaving the work area.',
        hazards: 'Fibre transfer to vehicles, welfare areas or homes can create secondary exposure.',
        controls: 'Provide suitable decontamination facilities and enforce the procedure.',
