        example: 'Sealed asbestos waste bags are placed in a controlled, secured waste container and protected from damage.',
        hazards: 'Torn bags, open skips or uncontrolled storage can release fibres.',
        controls: 'Use appropriate labelled packaging, secure storage and inspection.',
