        explanation: 'The final destination must be traceable and authorised.',
        example: 'A waste load is accompanied by the required transfer/manifest information and disposal evidence.',
        hazards: 'Illegal or uncontrolled disposal can expose the public and environment.',
        controls: 'Verify carrier and facility approval before movement and retain disposal evidence.',
        fieldCheck: 'Trace a completed load to the receiving facility.',
