        clause: '3.27(a)',
        title: 'Prevent contaminated reuse',
        meaning: 'Before building materials are recycled, procedures must ensure asbestos-contaminated materials are not reused unless successfully decontaminated as permitted.',
        explanation: 'Asbestos must not be hidden inside apparently reusable construction materials.',
        example: 'Demolition materials are screened and suspected asbestos-containing products are quarantined before entering the recycling process.',
        hazards: 'Redistribution can expose workers at recycling yards and future users.',
        controls: 'Screen, quarantine and remove contaminated materials from the recycling stream.',
        fieldCheck: 'Check the recycling yard\'s asbestos screening procedure.',
        commonMistake: 'Sending demolition waste directly to recycling without screening.',
        action: 'Stop the load and segregate suspect materials.',
        records: 'Screening records; quarantine records; waste transfer records.',
      ),
      CopGoldPoint(
        clause: '3.27(b)',
        title: 'Quarantine incoming material',
        meaning: 'Incoming construction materials intended for recycling should be quarantined to allow asbestos screening before distribution within the recycling yard.',
        explanation: 'Quarantine prevents one suspect load from contaminating a large processing area.',
        example: 'A dedicated quarantine zone is used until the material is checked.',
        hazards: 'Processing before screening can spread contamination through machinery and stockpiles.',
        controls: 'Use controlled quarantine, inspection and release criteria.',
        fieldCheck: 'Inspect quarantine records and stockpile labels.',
        commonMistake: 'Mixing unverified demolition materials with clean recycled material.',
        action: 'Re-segregate the material and assess contamination.',
        records: 'Quarantine register; inspection records; release records.',
      ),
    ],
