        title: 'Friable ACM requires enhanced control',
        meaning: 'Friable ACM should be removed using wet methods where reasonably practicable and within an enclosed area.',
        explanation: 'Friable material can release fibres readily when disturbed, so enclosure and wet methods are important controls.',
        example: 'Friable insulation is removed inside a sealed enclosure using controlled wet techniques.',
        hazards: 'High airborne fibre potential and contamination outside the work area.',
        controls: 'Use enclosure, wet method, negative pressure and specialist RPE as required by the approved plan.',
        fieldCheck: 'Check enclosure integrity, pressure and wetting controls before entry.',
        commonMistake: 'Treating friable and non-friable ACM as identical tasks.',
        action: 'Upgrade controls for friable ACM.',
        records: 'Plan of work; enclosure design; pressure logs; monitoring.',
      ),
      CopGoldPoint(
        clause: '3.28(c)',
        title: 'Isolate ventilation and air-conditioning',
        meaning: 'Ventilation and air-conditioning serving the asbestos work area should be shut down and vents sealed to prevent fibre entry into duct systems; relevant recirculated filters are replaced after completion as specified.',
        explanation: 'The objective is to stop fibres travelling beyond the enclosure through building services.',
        example: 'HVAC serving the work zone is isolated and openings are sealed before removal begins.',
        hazards: 'Contaminated ducts can distribute fibres to occupied areas.',
        controls: 'Coordinate isolation, sealing, filter replacement and restart checks.',
        fieldCheck: 'Physically verify vents and HVAC isolation.',
        commonMistake: 'Assuming the enclosure alone protects against duct contamination.',
        action: 'Stop work until service pathways are controlled.',
        records: 'HVAC isolation record; inspection; filter replacement record.',
      ),
      CopGoldPoint(
