        title: 'Negative air extraction and HEPA control',
        meaning: 'Negative-air equipment should provide controlled extraction through suitable HEPA filtration and be maintained to prevent release outside the enclosure.',
        explanation: 'The extraction system supports containment by maintaining negative pressure and filtering exhaust air.',
        example: 'A negative-air unit runs continuously through the removal/decontamination period with pressure monitoring and maintained filters.',
        hazards: 'Loss of extraction or filter integrity can release fibres.',
        controls: 'Use compliant HEPA units, pre-filters, alarms, inspection and controlled filter changes.',
        fieldCheck: 'Check pressure, alarms, filter condition and exhaust location.',
        commonMistake: 'Switching off extraction during active removal.',
        action: 'Stop work and restore containment before restart.',
        records: 'NPU logs; pressure records; filter records.',
      ),
    ],
