        title: 'Enclosure construction',
        meaning: 'The enclosure must be designed and built to contain the asbestos work and maintain controlled negative pressure.',
        explanation: 'The design should account for size, access, viewing, decontamination and emergency arrangements.',
        example: 'A sealed enclosure is connected to the decontamination unit and negative-air system.',
        hazards: 'Leaks or poor design can allow fibre escape.',
        controls: 'Use suitable plastic sheeting, sealed joints, controlled entry and adequate structural support.',
