        explanation: 'The aim is to prevent uncontrolled movement of contaminated personnel and materials.',
        example: 'Workers pass through the designated decontamination sequence rather than exiting directly into the building.',
        hazards: 'Cross-contamination can occur if the clean/dirty transition is poorly designed.',
        controls: 'Provide appropriate compartments, access control, cleaning facilities and procedures.',
