        hazards: 'Poor sealing can release residual fibres.',
        controls: 'Follow the approved glove-bag method and use suitable asbestos vacuuming where specified.',
        fieldCheck: 'Observe each step rather than accepting a completed bag without inspection.',
        commonMistake: 'Cutting the bag open or removing it before internal contamination is controlled.',
        action: 'Stop and re-establish containment.',
        records: 'Glove-bag inspection; waste record; work log.',
      ),
    ],
  ),
  CopGoldSection(
    title: '3.28.5. Wrap and Cut Removal Method',
    introduction: 'Provides a controlled method for redundant plant/equipment where the ACM can be completely wrapped before cutting.',
    points: <CopGoldPoint>[
      CopGoldPoint(
        clause: '3.28.5(a)',
        title: 'Double wrapping',
        meaning: 'The plant or equipment is double wrapped with 200 μm plastic and sealed so ACM is contained before the plant is separated.',
        explanation: 'The method aims to produce very low airborne fibre levels when suitable.',
        example: 'Redundant equipment with asbestos lagging is fully wrapped and taped before mechanical separation.',
        hazards: 'Puncturing or melting the wrapping can release fibres.',
        controls: 'Use appropriate wrapping, sealing and controlled cutting of exposed metal only.',
        fieldCheck: 'Inspect the wrap for holes and verify the cutting plan.',
        commonMistake: 'Cutting through wrapped ACM or melting the plastic.',
        action: 'Stop and repair the containment before cutting.',
        records: 'Wrap inspection; photographs; method statement.',
      ),
      CopGoldPoint(
        clause: '3.28.5(b)',
        title: 'Cut only exposed metal',
        meaning: 'Only exposed metal should be cut; if lagging must be removed to expose the cut point, a controlled method such as a suitable glove bag is used.',
        explanation: 'The asbestos-containing insulation remains sealed during the cutting operation.',
        example: 'A pipe section is exposed under controlled conditions, insulation is removed and bagged, and the pipe is cut at the prepared metal section.',
        hazards: 'Cutting ACM can create a high fibre release.',
        controls: 'Use controlled exposure, wetting, containment and suitable tools.',
        fieldCheck: 'Verify the cut location before operation.',
        commonMistake: 'Allowing saws or oxy-cutting to contact the asbestos material.',
        action: 'Stop the operation and re-establish a controlled cutting point.',
        records: 'Cutting permit; work plan; inspection record.',
      ),
    ],
  ),
  CopGoldSection(
    title: '3.29. Clearance to Reoccupy an Asbestos Work Area',
    introduction: 'Defines the clearance process before unprotected personnel can re-enter an asbestos work area.',
    points: <CopGoldPoint>[
      CopGoldPoint(
        clause: '3.29(a-c)',
        title: 'Independent clearance inspection and certificate',
        meaning: 'The work area requires a thorough clearance inspection by an independent competent ASC and a clearance certificate before reoccupation where required.',
        explanation: 'Clearance is a separate verification stage, not the contractor\'s own declaration that cleaning is complete.',
        example: 'The contractor completes cleaning, then the independent ASC performs the clearance inspection and issues the certificate when criteria are met.',
        hazards: 'Premature reoccupation can expose unprotected workers.',
        controls: 'Keep barriers intact until clearance is successfully completed.',
        fieldCheck: 'Check the identity and independence of the clearance assessor.',
        commonMistake: 'Removing barriers before clearance.',
        action: 'Maintain exclusion until the clearance process is complete.',
        records: 'Clearance inspection; certificate; barrier log.',
      ),
      CopGoldPoint(
        clause: '3.29.1',
        title: 'Visual inspection',
        meaning: 'Visual inspection confirms that removal is complete and there is no visible dust or debris, including on ledges, ducts, cracks, folds and crevices.',
        explanation: 'A visual inspection is necessary but does not replace clearance monitoring where monitoring is required.',
        example: 'The inspector uses adequate lighting and checks hidden ledges and service interfaces.',
        hazards: 'Residual dust can remain in locations not visible during a quick walk-through.',
        controls: 'Use a systematic inspection route and record findings.',
        fieldCheck: 'Check difficult-to-clean locations specifically.',
        commonMistake: 'Accepting a clean-looking floor while ignoring ledges and ducts.',
        action: 'Clean again and repeat the inspection.',
        records: 'Inspection checklist; photographs; cleaning record.',
      ),
      CopGoldPoint(
        clause: '3.29.2',
        title: 'Clearance air monitoring',
        meaning: 'Where required, clearance monitoring is undertaken by an independent competent person after cleaning and drying to demonstrate airborne fibre levels are below 0.01 fibres/mL.',
        explanation: 'For enclosed jobs, sampling is performed at the appropriate stages before and after enclosure removal as described by the CoP.',
        example: 'The final clearance sample is below the specified criterion before the area is released.',
        hazards: 'Premature release can expose future occupants.',
        controls: 'Use competent independent monitoring and retain results with the clearance certificate.',
        fieldCheck: 'Verify sampling locations, result and release decision.',
        commonMistake: 'Reoccupying because the visual inspection passed while clearance monitoring is incomplete.',
        action: 'Keep the area closed until required monitoring is satisfactory.',
        records: 'Clearance monitoring report; certificate; release record.',
      ),
      CopGoldPoint(
        clause: '3.29.3',
        title: 'Settled dust sampling',
        meaning: 'Settled dust sampling may support clearance as an indication of cleanliness but is not a measure of health risk.',
        explanation: 'The method should be interpreted by the competent person and not used to replace required air monitoring.',
        example: 'A dust sample is used as supporting evidence while the required visual and air clearance steps remain in place.',
        hazards: 'Misinterpreting dust results can create false confidence.',
        controls: 'Use settled dust sampling only within the competent clearance strategy.',
        fieldCheck: 'Check that dust results were not used as the sole release criterion.',
        commonMistake: 'Calling a low dust result a \'safe exposure\' result.',
        action: 'Apply the correct clearance criteria.',
        records: 'Dust-sampling report; clearance plan.',
      ),
    ],
  ),
  CopGoldSection(
    title: '3.30. Emergency Exposure to Asbestos',
    introduction: 'Defines immediate notification, investigation and health/environment monitoring after accidental asbestos exposure.',
    points: <CopGoldPoint>[
      CopGoldPoint(
        clause: '3.30(a-b)',
        title: 'Immediate notification and 24-hour written report',
        meaning: 'Where people have been exposed, the duty holder must notify the Building and Construction SRA and relevant competent authorities immediately and submit a written report within 24 hours, with exposure and current controls information.',
        explanation: 'Emergency exposure requires prompt regulatory and operational response.',
        example: 'A damaged enclosure exposes adjacent workers; the work stops, the area is controlled, immediate notification is made and the written report is prepared within the required timeframe.',
        hazards: 'Continued exposure and loss of evidence can worsen the event.',
        controls: 'Maintain emergency contacts, notification procedure and incident-reporting process.',
        fieldCheck: 'Check that the emergency plan contains current authority contacts.',
        commonMistake: 'Waiting until the next routine meeting to report exposure.',
        action: 'Activate emergency notification immediately and implement controls.',
        records: 'Initial notification; written report; incident record.',
      ),
      CopGoldPoint(
        clause: '3.30(c-d)',
        title: 'Root-cause investigation',
        meaning: 'An accidental exposure requires investigation of root causes and identification of additional controls.',
        explanation: 'The investigation should examine the failed barrier, planning, competence, supervision and environmental conditions.',
        example: 'The team finds that an outdated register caused an unplanned drill through ACM and adds a work-order asbestos verification gate.',
        hazards: 'Failure to learn from the event can allow recurrence.',
        controls: 'Use structured incident investigation and corrective-action tracking.',
        fieldCheck: 'Check that actions address root causes rather than only retraining.',
        commonMistake: 'Closing the event after a toolbox talk without correcting the system failure.',
        action: 'Implement systemic corrective actions and verify effectiveness.',
        records: 'Investigation; root-cause analysis; corrective action; effectiveness review.',
      ),
      CopGoldPoint(
        clause: '3.30(e)',
        title: 'Post-exposure health and environmental monitoring',
        meaning: 'The employer or duty holder must implement a programme to monitor the effects of emergency exposure on health and the environment.',
        explanation: 'Post-event monitoring must be coordinated with competent occupational-health and environmental functions.',
        example: 'Affected employees are referred through the appropriate occupational-health process and the contaminated area is assessed.',
        hazards: 'Unrecognised exposure or residual contamination may persist after the event.',
        controls: 'Document affected persons, exposure circumstances and follow-up requirements.',
        fieldCheck: 'Check follow-up actions and medical/environmental records are controlled.',
        commonMistake: 'Treating the event as closed after the area is cleaned.',
        action: 'Keep the exposure case open until required follow-up is completed.',
        records: 'Exposure register; occupational-health referral; environmental assessment.',
      ),
    ],
  ),
