        title: 'Pre-employment or pre-work medical evaluation',
        meaning: 'Before employment or commencement of asbestos work, the employer must have a physician evaluate relevant health factors, including lung-related disease considerations described by the CoP.',
        explanation: 'Medical fitness should be addressed before assigning asbestos work.',
        example: 'A new asbestos-removal worker completes the required occupational-health evaluation before starting the role.',
        hazards: 'Unsuitable assignment may place a worker at increased risk.',
